#include <cctype>
#include <map>
#include <string>

static bool isWordChar(char c)
{
    return std::isalnum(static_cast<unsigned char>(c)) || c == '_';
}

// Replaces each whole word of line that is a key of defines with its value.
std::string expand(const std::string& line, const std::map<std::string, std::string>& defines)
{
    std::string out;
    std::size_t i{ 0 };
    while (i < line.size())
    {
        if (!isWordChar(line[i]))
        {
            out += line[i];
            ++i;
            continue;
        }
        std::size_t start{ i };
        while (i < line.size() && isWordChar(line[i])) ++i;
        const std::string word{ line.substr(start, i - start) };
        const auto found{ defines.find(word) };
        out += (found != defines.end()) ? found->second : word;
    }
    return out;
}

unitTests:
#include <map>
const std::map<std::string, std::string> D{ { "MAX_HEALTH", "100" }, { "BONUS", "25" }, { "NAME", "\"Rook\"" } };
TEST("no macros leaves the line alone") { CHECK_EQ(expand("int x = 3;", D), std::string("int x = 3;")); }
TEST("one macro") { CHECK_EQ(expand("hp = MAX_HEALTH;", D), std::string("hp = 100;")); }
TEST("two macros") { CHECK_EQ(expand("hp = MAX_HEALTH + BONUS;", D), std::string("hp = 100 + 25;")); }
TEST("only whole words") { CHECK_EQ(expand("MAX_HEALTH_BAR = BONUS2;", D), std::string("MAX_HEALTH_BAR = BONUS2;")); }
TEST("macro at the very start and end") { CHECK_EQ(expand("BONUS*BONUS", D), std::string("25*25")); }
TEST("replacement text can be anything") { CHECK_EQ(expand("print(NAME)", D), std::string("print(\"Rook\")")); }
TEST("an empty line") { CHECK_EQ(expand("", D), std::string("")); }

